-- ── users tábla: address oszlop biztonságos hozzáadása ──
SET @dbname = DATABASE();
SET @tablename = 'users';
SET @columnname = 'address';
SET @preparedStatement = (
  SELECT IF(
    COUNT(*) = 0,
    'ALTER TABLE `users` ADD COLUMN `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL',
    'SELECT 1'
  )
  FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = @dbname
    AND TABLE_NAME   = @tablename
    AND COLUMN_NAME  = @columnname
);
PREPARE alterstmt FROM @preparedStatement;
EXECUTE alterstmt;
DEALLOCATE PREPARE alterstmt;


-- ====================================================
-- PATCH: order_items tábla + seed adatok
-- Futtatd ezt phpMyAdminban EGYSZER a db_schema.sql
-- és products.sql importálása UTÁN
-- ====================================================

-- ── order_items tábla ─────────────────────────────
CREATE TABLE IF NOT EXISTS `order_items` (
  `id`           int          NOT NULL AUTO_INCREMENT,
  `order_id`     int          NOT NULL,
  `product_id`   int          NOT NULL,
  `quantity`     int          NOT NULL DEFAULT 1,
  `unit_price`   int          NOT NULL DEFAULT 0,
  `total_amount` int          NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order_id` (`order_id`),
  KEY `idx_order_items_product_id` (`product_id`),
  CONSTRAINT `order_items_ibfk_order`
    FOREIGN KEY (`order_id`)   REFERENCES `orders`   (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_product`
    FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── support_tickets tábla ─────────────────────────
CREATE TABLE IF NOT EXISTS `support_tickets` (
    `id`          INT AUTO_INCREMENT PRIMARY KEY,
    `email`       VARCHAR(255) NOT NULL,
    `message`     TEXT NOT NULL,
    `resolved`    TINYINT(1) NOT NULL DEFAULT 0,
    `created_at`  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `resolved_at` TIMESTAMP NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

